"""Generate a FastMCP server whose tools mirror an OpenAPI 3.0 spec."""

from typing import Any

import httpx
from fastmcp import FastMCP


def build_mcp_server(
    openapi_spec: dict[str, Any],
    client: httpx.AsyncClient,
    name: str = "OpenAPI Server",
) -> FastMCP:
    """Build a FastMCP server exposing tools generated from an OpenAPI spec.

    Args:
        openapi_spec: Minimal OpenAPI 3.0 specification as a dict.
        client: httpx.AsyncClient pre-configured with the API base URL.
        name: Name to give the generated MCP server.

    Returns:
        A FastMCP server instance with tools mirroring the OpenAPI operations.
    """
    return FastMCP.from_openapi(
        openapi_spec=openapi_spec,
        client=client,
        name=name,
    )


if __name__ == "__main__":
    example_spec: dict[str, Any] = {
        "openapi": "3.0.0",
        "info": {"title": "Example API", "version": "1.0.0"},
        "paths": {
            "/items/{item_id}": {
                "get": {
                    "operationId": "getItem",
                    "summary": "Get an item by ID",
                    "parameters": [
                        {
                            "name": "item_id",
                            "in": "path",
                            "required": True,
                            "schema": {"type": "integer"},
                        }
                    ],
                    "responses": {"200": {"description": "The requested item"}},
                }
            }
        },
    }

    example_client = httpx.AsyncClient(base_url="https://api.example.com")
    mcp_server = build_mcp_server(example_spec, example_client, name="Example API Server")
    mcp_server.run()

